    onSuccess: (data, variables, context) => {
      // Invalidate the users query so the list reflects the new role
      queryClient.invalidateQueries({ queryKey: ['users'] });

      // Show success message
      addNotification({ type: 'success', title: 'Success', message: 'User role updated successfully' });

      onSuccess?.(data as any, variables, context);
    },
    ...restConfig,
    mutationFn: updateUserRole,
  });
};

import { Spinner } from '@/components/ui/spinner';
import { Table } from '@/components/ui/table';
import { formatDate } from '@/utils/format';

import { useUsers } from '../api/get-users';
import { useUpdateUserRole } from '../api/update-role';

import { DeleteUser } from './delete-user';

export const UsersList = () => {
  const usersQuery = useUsers();
  const updateRoleMutation = useUpdateUserRole();

  if (usersQuery.isLoading) {
    return (
      <div className="flex h-48 w-full items-center justify-center">
        <Spinner size="lg" />
      </div>
    );
  }

  const users = usersQuery.data?.data;

  if (!users) return null;

  const handleRoleChange = (userId: string, role: string) => {
    updateRoleMutation.mutate({ 
      id: userId, 
      data: { role: role as 'ADMIN' | 'USER' } 
    });
  };

  return (
    <Table
      data={users}
      columns={[
        {
          title: 'First Name',
          field: 'firstName',
        },
        {
          title: 'Last Name',
          field: 'lastName',
        },
        {
          title: 'Email',
          field: 'email',
        },
        {
          title: 'Role',
          field: 'role',
          Cell({ entry }) {
            if (!entry?.id || !entry?.role) return <span>{entry?.role}</span>;
            return (
              <select
                value={entry.role}
                onChange={(e) => handleRoleChange(entry.id, e.target.value)}
                disabled={updateRoleMutation.isLoading && updateRoleMutation.variables?.id === entry.id}
                className="rounded border border-gray-300 px-2 py-1 text-sm focus:border-blue-500 focus:ring-blue-500 w-full"
              >
                <option value="ADMIN">Admin</option>
                <option value="USER">User</option>
              </select>
            );
          },
        },
        {
          title: 'Created At',
          field: 'createdAt',
          Cell({ entry: { createdAt } }) {
            return <span>{formatDate(createdAt)}</span>;
          },
        },
        {
          title: '',
          field: 'id',
          Cell({ entry: { id } }) {
            return <DeleteUser id={id} />;
          },
        },
      ]}
    />
  );
};

import { HttpResponse, http } from 'msw';

import { env } from '@/config/env';

import { db, persistDb } from '../db';
import {
  requireAuth,
  requireAdmin,
  sanitizeUser,
  networkDelay,
} from '../utils';

type ProfileBody = {
  email: string;
  firstName: string;
  lastName: string;
  bio: string;
};

export const usersHandlers = [
  http.get(`${env.API_URL}/users`, async ({ cookies }) => {
    await networkDelay();

    try {
      const { user, error } = requireAuth(cookies);
      if (error) {
        return HttpResponse.json({ message: error }, { status: 401 });
      }
      const result = db.user
        .findMany({
          where: {
            teamId: {
              equals: user?.teamId,
            },
          },
        })
        .map(sanitizeUser);

      return HttpResponse.json({ data: result });
    } catch (error: any) {
      return HttpResponse.json(
        { message: error?.message || 'Server Error' },
        { status: 500 },
      );
    }
  }),

  http.patch(`${env.API_URL}/users/profile`, async ({ request, cookies }) => {
    await networkDelay();

    try {
      const { user, error } = requireAuth(cookies);
      if (error) {
        return HttpResponse.json({ message: error }, { status: 401 });
      }
      const data = (await request.json()) as ProfileBody;
      const result = db.user.update({
        where: {
          id: {
            equals: user?.id,
          },
        },
        data,
      });
      await persistDb('user');
      return HttpResponse.json(result);
    } catch (error: any) {
      return HttpResponse.json(
        { message: error?.message || 'Server Error' },
        { status: 500 },
      );
    }
  }),

  http.patch(`${env.API_URL}/users/:userId/role`, async ({ request, cookies, params }) => {
    await networkDelay();

    try {
      const { user, error } = requireAuth(cookies);
      if (error) {
        return HttpResponse.json({ message: error }, { status: 401 });
      }
      requireAdmin(user);

      const userId = params.userId as string;
      const data = (await request.json()) as { role: string };

      const result = db.user.update({
        where: {
          id: {
            equals: userId,
          },
          teamId: {
            equals: user?.teamId,
          },
        },
        data: { role: data.role },
      });

      await persistDb('user');
      return HttpResponse.json(result);
    } catch (error: any) {
      return HttpResponse.json(
        { message: error?.message || 'Server Error' },
        { status: 500 },
      );
    }
  }),

  http.delete(`${env.API_URL}/users/:userId`, async ({ cookies, params }) => {
    await networkDelay();

    try {
      const { user, error } = requireAuth(cookies);
      if (error) {
        return HttpResponse.json({ message: error }, { status: 401 });
      }
      const userId = params.userId as string;
      requireAdmin(user);
      const result = db.user.delete({
        where: {
          id: {
            equals: userId,
          },
          teamId: {
            equals: user?.teamId,
          },
        },
      });
      await persistDb('user');
      return HttpResponse.json(result);
    } catch (error: any) {
      return HttpResponse.json(
        { message: error?.message || 'Server Error' },
        { status: 500 },
      );
    }
  }),
];

I implemented the feature by:

1.  **Creating the API Hook:** Added `src/features/users/api/update-role.ts` which defines the `updateUserRole` mutation and `useUpdateUserRole` hook. The hook automatically invalidates the `['users']` query key on success to refresh the list, and triggers a success notification.
2.  **Adding the Mock API Endpoint:** Updated `src/testing/mocks/handlers/users.ts` with the new `PATCH /users/:userId/role` handler. It validates authentication/admin rights, updates the user's role in the in-memory DB, and persists the changes.
3.  **Updating the Users Table:** Modified `src/features/users/components/users-list.tsx` to replace the static role text with a `<select>` input in each row. The dropdown triggers the role update mutation on change, and the UI disables other inputs while the request is in-flight to prevent race conditions.

